def transform(grid):
    # For each outlined rectangle, fill its interior based on shape parity:
    # odd-by-odd interior -> 7; otherwise -> 2.
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    bg=max(set(v for row in grid for v in row), key=lambda v:sum(x==v for row in grid for x in row))
    for color in set(v for row in grid for v in row)-{bg}:
        for r0 in range(h):
            for r1 in range(r0+2,h):
                for c0 in range(w):
                    for c1 in range(c0+2,w):
                        if all(grid[r0][c]==color and grid[r1][c]==color for c in range(c0,c1+1)) and all(grid[r][c0]==color and grid[r][c1]==color for r in range(r0,r1+1)):
                            inside=[grid[r][c] for r in range(r0+1,r1) for c in range(c0+1,c1)]
                            if inside and all(v==bg for v in inside):
                                fill=7 if ((r1-r0-1)*(c1-c0-1)) % 2 == 1 else 2
                                for r in range(r0+1,r1):
                                    for c in range(c0+1,c1): out[r][c]=fill
    return out

